function openSaleModal(){const ps=cache.cashier?.products||[];openModal('بيع سريع','POS',`<div class="muted">اختر المنتج وأدخل الكمية.</div><div class="form-grid"><div class="field"><label>المنتج</label><select id="f-product">${ps.map(p=>`<option value="${p.id}">${esc(p.name)} — ${money(p.price)}</option>`).join('')}</select></div>${field('qty','الكمية','1','number')}${field('paid','المدفوع','0','number')}</div><div class="form-actions"><button class="btn primary" id="modal-save">إنشاء الفاتورة</button></div>`,async()=>{const pid=Number(read('product'));const p=ps.find(x=>x.id===pid);const r=await api('create_sale')({cart:[{product_id:pid,quantity:Number(read('qty')),price:p.price}],paid:Number(read('paid')),payment_method:'نقدي',tax_rate:0});if(!r.ok)throw new Error(r.error||'تعذر البيع');toast(`فاتورة ${r.invoice} — ${money(r.total)}`);await softRefresh('sales')})}
