$('server-save').onclick=saveServer;const adminCfg=$('login-admin-settings');if(adminCfg)adminCfg.onclick=()=>$('login-server-panel')?.classList.toggle('hidden');$('login-btn').onclick=doLogin;$('login-pass').onkeydown=e=>{if(e.key==='Enter')doLogin()};$('login-user').onkeydown=e=>{if(e.key==='Enter')$('login-pass').focus()};$('logout-btn').onclick=async()=>{try{await api('logout') }finally{showLogin()}};$('refresh-btn').onclick=()=>loadModule(current);$('top-settings-btn').onclick=()=>$('settings-dropdown')?.classList.toggle('hidden');document.querySelectorAll('[data-settings-shortcut]').forEach(b=>b.onclick=()=>{const tab=b.dataset.settingsShortcut;$('settings-dropdown')?.classList.add('hidden');loadModule('settings').then(()=>document.querySelector(`[data-settings-tab=\"${tab}\"]`)?.click())});document.addEventListener('click',e=>{if(!e.target.closest('.settings-menu'))$('settings-dropdown')?.classList.add('hidden')});$('fullscreen-btn').onclick=async()=>{const fn=api('window_toggle_fullscreen');if(fn)await fn()};$('modal-close').onclick=closeModal;$('modal').onclick=e=>{if(e.target.id==='modal')closeModal()};$('global-search').oninput=e=>{const q=e.target.value.trim().toLowerCase();const items=[...document.querySelectorAll('#top-nav .nav-item')];items.forEach(b=>{const hit=!q||b.textContent.toLowerCase().includes(q)||String(b.title||'').toLowerCase().includes(q);b.style.display=hit?'flex':'none'});if(q){document.querySelectorAll('#top-nav .nav-group').forEach(g=>g.classList.toggle('collapsed',!g.querySelector('.nav-item[style=\"display: flex;\"]')))}};
