window.loadModule=loadModule;window.renderModule=renderModule;window.closeModal=closeModal;

(function(){
  function bindScroll(el){ if(!el || el.dataset.scrollBound) return; el.dataset.scrollBound='1'; el.addEventListener('wheel',ev=>{ if(el.scrollHeight>el.clientHeight){ ev.preventDefault(); el.scrollTop += ev.deltaY; } },{passive:false}); el.addEventListener('mousedown',ev=>{ if(ev.button!==1) return; ev.preventDefault(); const startY=ev.clientY,startTop=el.scrollTop; const move=e=>{el.scrollTop=startTop-(e.clientY-startY)*1.6}; const up=()=>{window.removeEventListener('mousemove',move);window.removeEventListener('mouseup',up)}; window.addEventListener('mousemove',move);window.addEventListener('mouseup',up); }); }
  const ready=()=>{bindScroll($('nav'));bindScroll($('workspace'));}; if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',ready);else ready();
})();

window.uploadCustomAsset=uploadCustomAsset; window.chooseAndUploadCustomAsset=chooseAndUploadCustomAsset;
